"use client";

import { useState } from "react";
import { PillToggle } from "@/components/ui/pill-toggle";
import { HeroSection } from "@/components/dashboard/hero-section";
import { RecentRuns } from "@/components/dashboard/recent-runs";
import { Footer } from "@/components/dashboard/footer";
import { Sidebar } from "@/components/jobs/sidebar";
import { JobDetail } from "@/components/jobs/job-detail";
import { RunLogViewer } from "@/components/jobs/run-log-viewer";
import { JobEditForm } from "@/components/jobs/job-edit-form";
import { DeleteDialog } from "@/components/jobs/delete-dialog";
import { jobs } from "@/lib/mock-data";
import {
  Cog6ToothIcon,
  ChevronDownIcon,
  LinkIcon,
} from "@heroicons/react/20/solid";

const views = [
  { label: "Dashboard", value: "dashboard" },
  { label: "Jobs", value: "jobs" },
];

export default function Home() {
  const [view, setView] = useState("dashboard");

  // Jobs view state
  const [selectedJobId, setSelectedJobId] = useState<string | null>(null);
  const [activePanel, setActivePanel] = useState<"overview" | "log" | "edit">(
    "overview"
  );
  const [selectedRunId, setSelectedRunId] = useState<string | null>(null);
  const [showDeleteDialog, setShowDeleteDialog] = useState(false);

  const handleSelectJob = (id: string) => {
    setSelectedJobId(id);
    setActivePanel("overview");
    setSelectedRunId(null);
  };

  const handleDeselectJob = () => {
    setSelectedJobId(null);
    setActivePanel("overview");
    setSelectedRunId(null);
  };

  const handleSelectRun = (runId: string) => {
    setSelectedRunId(runId);
    setActivePanel("log");
  };

  const handleBackToOverview = () => {
    setActivePanel("overview");
    setSelectedRunId(null);
  };

  const handleSetPanel = (panel: "overview" | "log" | "edit") => {
    setActivePanel(panel);
    if (panel !== "log") setSelectedRunId(null);
  };

  const selectedJob = selectedJobId
    ? jobs.find((j) => j.id === selectedJobId)
    : null;

  return (
    <div className="flex flex-col min-h-screen">
      {/* ── Top Bar ───────────────────────────────────────────────────────── */}
      <header className="flex items-center px-5 py-3 border-b border-border bg-surface/60 backdrop-blur-sm">
        {/* Settings gear (left) */}
        <button
          className="flex items-center justify-center h-8 w-8 rounded-lg text-text-secondary hover:text-text-primary hover:bg-surface-elevated transition-colors cursor-pointer"
          aria-label="Settings"
        >
          <Cog6ToothIcon className="h-4.5 w-4.5" />
        </button>

        {/* Centered pill toggle */}
        <div className="flex-1 flex justify-center">
          <PillToggle value={view} onChange={setView} options={views} />
        </div>

        {/* Instance switcher (right) */}
        <button className="flex items-center gap-1.5 text-sm text-text-secondary hover:text-text-primary transition-colors cursor-pointer">
          <LinkIcon className="h-3.5 w-3.5 text-primary" />
          <span className="font-medium">Local</span>
          <ChevronDownIcon className="h-4 w-4 opacity-50" />
        </button>
      </header>

      {/* ── Content ───────────────────────────────────────────────────────── */}
      {view === "dashboard" ? (
        <DashboardView onNavigateJobs={() => setView("jobs")} />
      ) : (
        <>
          <div className="flex flex-1 overflow-hidden">
            <Sidebar
              selectedJobId={selectedJobId}
              onSelectJob={handleSelectJob}
              onDeselectJob={handleDeselectJob}
              onSelectRun={handleSelectRun}
              onSetPanel={handleSetPanel}
              onDeleteClick={() => setShowDeleteDialog(true)}
              selectedRunId={selectedRunId}
            />

            {/* Main content area */}
            {selectedJobId ? (
              activePanel === "log" && selectedRunId ? (
                <RunLogViewer
                  runId={selectedRunId}
                  onBackToOverview={handleBackToOverview}
                />
              ) : activePanel === "edit" ? (
                <JobEditForm
                  jobId={selectedJobId}
                  onCancel={handleBackToOverview}
                />
              ) : (
                <JobDetail jobId={selectedJobId} />
              )
            ) : (
              <JobListMain onSelectJob={handleSelectJob} />
            )}
          </div>

          {/* Delete confirmation dialog */}
          {showDeleteDialog && selectedJob && (
            <DeleteDialog
              jobName={selectedJob.name}
              onConfirm={() => {
                setShowDeleteDialog(false);
                handleDeselectJob();
              }}
              onCancel={() => setShowDeleteDialog(false)}
            />
          )}
        </>
      )}
    </div>
  );
}

/* ── Dashboard View ────────────────────────────────────────────────────── */
function DashboardView({ onNavigateJobs }: { onNavigateJobs: () => void }) {
  return (
    <div className="flex flex-col flex-1">
      <main className="flex-1 mx-auto w-full max-w-6xl px-6 py-8 space-y-8">
        <HeroSection onNavigateJobs={onNavigateJobs} />
        <RecentRuns />
      </main>
      <Footer />
    </div>
  );
}

/* ── Job List Main (no job selected) ─────────────────────────────────────── */
function JobListMain({
  onSelectJob,
}: {
  onSelectJob: (id: string) => void;
}) {
  return (
    <div className="flex-1 overflow-y-auto p-6">
      <div className="flex items-center justify-between mb-5">
        <h1 className="text-xl font-semibold text-text-primary">All Jobs</h1>
      </div>

      {/* Job cards grid */}
      <div className="grid grid-cols-1 gap-3 sm:grid-cols-2 lg:grid-cols-3">
        {jobs.map((job) => (
          <button
            key={job.id}
            onClick={() => onSelectJob(job.id)}
            className="rounded-lg border border-border bg-surface p-4 text-left transition-all duration-200 hover:border-primary/20 hover:shadow-[0_0_16px_-4px_oklch(0.70_0.15_55_/_0.1)] cursor-pointer group"
          >
            <div className="flex items-start gap-3 mb-3">
              <span
                className={`mt-0.5 h-2.5 w-2.5 rounded-full flex-shrink-0 ${
                  job.status === "ok"
                    ? "bg-success"
                    : job.status === "failed"
                      ? "bg-error"
                      : job.status === "running"
                        ? "bg-info animate-pulse"
                        : "bg-text-secondary/30"
                }`}
              />
              <div className="min-w-0 flex-1">
                <p className="text-sm font-medium text-text-primary truncate group-hover:text-primary transition-colors">
                  {job.name}
                </p>
                <p className="text-[11px] font-mono text-text-secondary/60 mt-0.5 truncate">
                  {job.schedule || "No schedule"}
                </p>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-x-4 gap-y-1 text-[11px]">
              <div>
                <span className="text-text-secondary/50">Next Run</span>
                <p className="text-text-secondary font-mono">
                  {job.nextRun || "N/A"}
                </p>
              </div>
              <div>
                <span className="text-text-secondary/50">Status</span>
                <p>
                  {job.enabled ? (
                    <span className="text-success/80">Enabled</span>
                  ) : (
                    <span className="text-text-secondary/40">Disabled</span>
                  )}
                </p>
              </div>
              <div>
                <span className="text-text-secondary/50">Mode</span>
                <p className="text-text-secondary font-mono">
                  {job.scheduleMode}
                </p>
              </div>
              <div>
                <span className="text-text-secondary/50">Timeout</span>
                <p className="text-text-secondary font-mono">{job.timeout}</p>
              </div>
            </div>
          </button>
        ))}
      </div>
    </div>
  );
}
