"use client";

import { cn } from "@/lib/utils";
import { jobs, runs, type Job, type JobStatus, relativeTime } from "@/lib/mock-data";
import { Button } from "@/components/ui/button";
import {
  PlusIcon,
  ArrowLeftIcon,
  PlayIcon,
  PencilSquareIcon,
  TrashIcon,
} from "@heroicons/react/20/solid";

/* ── Status dot color mapping ────────────────────────────────────────────── */
const statusDot: Record<JobStatus, string> = {
  ok: "bg-success",
  failed: "bg-error",
  running: "bg-info",
  disabled: "bg-text-secondary/30",
};

/* ── Types ───────────────────────────────────────────────────────────────── */
interface SidebarProps {
  selectedJobId: string | null;
  onSelectJob: (id: string) => void;
  onDeselectJob: () => void;
  onSelectRun: (runId: string) => void;
  onSetPanel: (panel: "overview" | "log" | "edit") => void;
  onDeleteClick: () => void;
  selectedRunId: string | null;
}

/* ── List View Sidebar (State 1) ─────────────────────────────────────────── */
function ListViewSidebar({
  selectedJobId,
  onSelectJob,
}: {
  selectedJobId: string | null;
  onSelectJob: (id: string) => void;
}) {
  return (
    <>
      {/* Header */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-border">
        <h2 className="text-xs font-semibold uppercase tracking-wider text-text-secondary">
          Jobs
        </h2>
        <Button variant="primary" size="sm" className="h-7 text-xs gap-1">
          <PlusIcon className="h-3.5 w-3.5" />
          Create
        </Button>
      </div>

      {/* Section label */}
      <div className="px-4 pt-3 pb-1.5">
        <p className="text-[10px] font-semibold uppercase tracking-wider text-text-secondary/50">
          Recent Jobs
        </p>
      </div>

      {/* Job list */}
      <nav className="flex-1 overflow-y-auto pb-2">
        {jobs.map((job) => (
          <button
            key={job.id}
            onClick={() => onSelectJob(job.id)}
            className={cn(
              "w-full flex items-start gap-3 px-4 py-3 text-left transition-colors cursor-pointer",
              selectedJobId === job.id
                ? "bg-surface-elevated"
                : "hover:bg-surface-elevated/50"
            )}
          >
            {/* Status dot */}
            <span
              className={cn(
                "mt-1.5 h-2.5 w-2.5 rounded-full flex-shrink-0",
                statusDot[job.status],
                job.status === "running" && "animate-pulse"
              )}
            />

            {/* Job info */}
            <div className="min-w-0 flex-1">
              <p className="text-sm font-medium text-text-primary truncate">
                {job.name}
              </p>
              <p className="text-[11px] text-text-secondary/60 mt-0.5">
                {job.nextRun ? `Next: ${job.nextRun}` : "Not scheduled"}
              </p>
              <p className="text-[10px] mt-0.5">
                {job.enabled ? (
                  <span className="text-success/70">Enabled</span>
                ) : (
                  <span className="text-text-secondary/40">Disabled</span>
                )}
              </p>
            </div>
          </button>
        ))}
      </nav>
    </>
  );
}

/* ── Detail View Sidebar (State 2) ───────────────────────────────────────── */
function DetailViewSidebar({
  jobId,
  onBack,
  onSelectRun,
  onSetPanel,
  onDeleteClick,
  selectedRunId,
}: {
  jobId: string;
  onBack: () => void;
  onSelectRun: (runId: string) => void;
  onSetPanel: (panel: "overview" | "log" | "edit") => void;
  onDeleteClick: () => void;
  selectedRunId: string | null;
}) {
  const job = jobs.find((j) => j.id === jobId);
  if (!job) return null;

  const jobRuns = runs.filter((r) => r.jobId === jobId).slice(0, 5);

  return (
    <>
      {/* Header */}
      <div className="px-4 py-3 border-b border-border">
        <h2 className="text-xs font-semibold uppercase tracking-wider text-text-secondary">
          Jobs
        </h2>
      </div>

      {/* Back button */}
      <button
        onClick={onBack}
        className="flex items-center gap-2 w-full px-4 py-2.5 text-sm text-text-secondary hover:text-text-primary transition-colors cursor-pointer border-b border-border"
      >
        <ArrowLeftIcon className="h-3.5 w-3.5" />
        <span className="font-medium">Back to all jobs</span>
      </button>

      {/* Management section */}
      <div className="px-4 py-3 border-b border-border">
        <p className="text-[10px] font-semibold uppercase tracking-wider text-text-secondary/50 mb-2.5">
          Management
        </p>
        <div className="flex flex-col gap-1.5">
          <Button
            variant="primary"
            size="sm"
            className="w-full justify-start"
            onClick={() => onSetPanel("overview")}
          >
            <PlayIcon className="h-3.5 w-3.5" />
            Trigger
          </Button>
          <Button
            variant="secondary"
            size="sm"
            className="w-full justify-start"
            onClick={() => onSetPanel("edit")}
          >
            <PencilSquareIcon className="h-3.5 w-3.5" />
            Edit
          </Button>
          <Button
            variant="destructive"
            size="sm"
            className="w-full justify-start"
            onClick={onDeleteClick}
          >
            <TrashIcon className="h-3.5 w-3.5" />
            Delete
          </Button>
        </div>
      </div>

      {/* Recent Runs */}
      <div className="flex-1 overflow-y-auto">
        <div className="px-4 pt-3 pb-1.5">
          <p className="text-[10px] font-semibold uppercase tracking-wider text-text-secondary/50">
            Recent Runs
          </p>
        </div>
        <div className="pb-2">
          {jobRuns.length === 0 ? (
            <p className="px-4 py-2 text-xs text-text-secondary/50">
              No runs yet.
            </p>
          ) : (
            jobRuns.map((run) => (
              <button
                key={run.id}
                onClick={() => onSelectRun(run.id)}
                className={cn(
                  "w-full flex items-center gap-2.5 px-4 py-2 text-left transition-colors cursor-pointer",
                  selectedRunId === run.id
                    ? "bg-surface-elevated"
                    : "hover:bg-surface-elevated/50"
                )}
              >
                <span
                  className={cn(
                    "h-2 w-2 rounded-full flex-shrink-0",
                    run.status === "success" && "bg-success",
                    run.status === "failed" && "bg-error",
                    run.status === "running" && "bg-info animate-pulse",
                    run.status === "killed" && "bg-warning"
                  )}
                />
                <div className="min-w-0 flex-1">
                  <span className="text-xs font-mono text-text-primary truncate block">
                    Run {run.id.slice(2)}
                  </span>
                </div>
                <span className="text-[10px] font-mono text-text-secondary/50 flex-shrink-0">
                  {relativeTime(run.started)}
                </span>
              </button>
            ))
          )}
        </div>
      </div>
    </>
  );
}

/* ── Exported Sidebar ────────────────────────────────────────────────────── */
export function Sidebar({
  selectedJobId,
  onSelectJob,
  onDeselectJob,
  onSelectRun,
  onSetPanel,
  onDeleteClick,
  selectedRunId,
}: SidebarProps) {
  return (
    <aside className="flex w-64 flex-col border-r border-border bg-surface overflow-hidden flex-shrink-0">
      {selectedJobId ? (
        <DetailViewSidebar
          jobId={selectedJobId}
          onBack={onDeselectJob}
          onSelectRun={onSelectRun}
          onSetPanel={onSetPanel}
          onDeleteClick={onDeleteClick}
          selectedRunId={selectedRunId}
        />
      ) : (
        <ListViewSidebar
          selectedJobId={selectedJobId}
          onSelectJob={onSelectJob}
        />
      )}
    </aside>
  );
}
